// Equality and null-check branches in the optimizing tier: values in the window of every
// kind, loose coercions that call user code, numbers held in registers against window values.
var out = [];
var objA = {}, objB = {};
var coerce = { valueOf: function () { return 7; } };
var vals = [0, -0, 1, 7, 2.5, NaN, Infinity, "", "0", "7", "abc", true, false, null, undefined, objA, objB, coerce, [], [7], Symbol.iterator, 10n, 7n];

function eqCount(a, b, n) {
    var c = 0;
    for (var i = 0; i < n; i++) {
        if (a == b) c++;
        if (a != b) c += 10;
        if (a === b) c += 100;
        if (a !== b) c += 1000;
    }
    return c;
}
function nullCount(a, n) {
    var c = 0;
    for (var i = 0; i < n; i++) {
        if (a == null) c++;
        if (a != null) c += 10;
        if (a === undefined) c += 100;
        if (a !== null) c += 1000;
    }
    return c;
}
var rows = [];
for (var i = 0; i < vals.length; i++) {
    var row = [];
    for (var j = 0; j < vals.length; j++) row.push(eqCount(vals[i], vals[j], 30));
    rows.push(row.join(","));
}
out.push(rows.join(";"));
var nulls = [];
for (var i = 0; i < vals.length; i++) nulls.push(nullCount(vals[i], 30));
out.push(nulls.join(","));

// A numeric counter against a window value of any kind.
function countTo(limit, n) {
    var hits = 0;
    for (var i = 0; i < n; i++) {
        if (i === limit) hits++;
        if (i == limit) hits += 10;
        if (i != limit) hits += 100;
    }
    return hits;
}
out.push(countTo(5, 20), countTo("5", 20), countTo(5.5, 20), countTo(null, 20), countTo(coerce, 20));

// Two numbers computed in registers.
function numbers(n) {
    var hits = 0, x = 0.5, y = 0;
    for (var i = 0; i < n; i++) {
        x = x + 0.5;
        y = y + 1;
        if (x == y) hits++;
        if (x !== y) hits += 10;
    }
    return hits;
}
out.push(numbers(50));

// Loose equality that calls user code which throws, and which changes a register.
function thrower(a, b) {
    var c = 0;
    for (var i = 0; i < 20; i++) { try { if (a == b) c++; } catch (e) { c += 100; } }
    return c;
}
out.push(thrower({ valueOf: function () { throw 1; } }, 3), thrower({ valueOf: function () { return 3; } }, 3));

// A loop-carried number that is live across a branch on window values.
function carried(a, b, n) {
    var s = 0;
    for (var i = 0; i < n; i++) {
        s += i * 0.5;
        if (a == b) s += 1;
        else s -= 1;
    }
    return s;
}
out.push(carried(objA, objA, 40), carried(objA, objB, 40), carried(null, undefined, 40), carried("3", 3, 40));

var line = out.join("|");
